#pragma once
static void checkAutomaticChargeSides(App& app,const std::string& dir){
    auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("charge side: "+why);};auto& s=app.s;int cases=0;
    std::vector<Vec2> directions{{25,-14},{25,14},{-25,-14},{-25,14},{0,-30},{0,0}};
    Session display;
    for(int z:{7,8,16})for(int q:{-1,1})for(bool marker:{false,true})for(size_t k=0;k<directions.size();++k){
        s.cancel();s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());s.doc.setDefaultFont("Arial");ObjectId host,parent;s.doc.addAtom(Vec2(80,80),z,&host);bool connected=length(directions[k])>0;
        if(connected){s.doc.addAtom(Vec2(80,80)+directions[k],6,&parent);s.doc.addBond(host,parent,nullptr);}auto sem=s.doc.atoms().alive(host)->semantics;sem.charge=q;sem.implicitHydrogens=z==7?(q>0?(connected?3:4):(connected?1:2)):q>0?(connected?2:3):(connected?0:1);sem.showLabel=true;s.doc.setAtomLabel(host,elementSymbol(z));s.doc.setAtomSemantics(host,sem);if(marker)s.doc.extensions(ObjectRef(ObjectKind::Atom,host)).set("pst.attr.MoleculeStudioChargePosition","auto");
        auto before=s.doc.digest();s.refresh();const auto& visual=arrows::mechanismVisualBoxes(s.doc).at(host);require(visual.hasCharge&&!visual.labelGlyphs.empty(),"charge and atomic glyphs exist");auto body=arrows::mechanismLabelEnvelope(visual);bool left=k<2;
        require(left?visual.charge.max.x<body.min.x:visual.charge.min.x>body.max.x,"automatic charge occupies the free side of the formula");require(s.doc.digest()==before,"automatic rendering never changes chemistry or coordinates");
        if(z==16&&q==-1&&k==0){auto& bag=s.doc.extensions(ObjectRef(ObjectKind::Atom,host));bag.set("pst.attr.MoleculeStudioChargePosition","0.95 -0.6");s.doc.bumpStructure();s.refresh();auto area=arrows::mechanismVisualBoxes(s.doc).at(host).charge;auto center=(area.min+area.max)*.5;require(length(center-(s.doc.atoms().alive(host)->position+Vec2(9.5,-6)))<1e-7,"manual charge placement overrides automatic left preference");}
        if(z==16&&!marker){auto offset=Vec2((cases%12)*60-80,(cases/12)*75-80);require(studioio::append(s.doc,display.doc,s.all(),offset,nullptr).ok(),"collect charge side display cases");}++cases;
    }
    for(int q:{-2,2})for(size_t k=0;k<4;++k){
        s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());ObjectId a,b;s.doc.addAtom(Vec2(80,80),16,&a);s.doc.addAtom(Vec2(80,80)+directions[k],6,&b);s.doc.addBond(a,b,nullptr);auto sem=s.doc.atoms().alive(a)->semantics;sem.charge=q;sem.implicitHydrogens=0;sem.showLabel=true;s.doc.setAtomSemantics(a,sem);s.refresh();auto visual=arrows::mechanismVisualBoxes(s.doc).at(a);auto body=arrows::mechanismLabelEnvelope(visual);require(visual.hasCharge&&(k<2?visual.charge.max.x<body.min.x:visual.charge.min.x>body.max.x),"magnitude and sign of a multiple charge move together");++cases;
    }
    // A manually placed remote charge survives strict generation unchanged.
    {
        Document d;ObjectId o,c,n,me,i,ci;d.addAtom(Vec2(80,80),8,&o);d.addAtom(Vec2(105,95),6,&c);d.addAtom(Vec2(130,80),7,&n);d.addAtom(Vec2(180,80),6,&me);d.addAtom(Vec2(205,80),53,&i);d.addBond(o,c,nullptr);d.addBond(c,n,nullptr);d.addBond(me,i,&ci);
        for(auto id:{o,c,n,me,i}){auto sem=d.atoms().alive(id)->semantics;sem.charge=id==o?-1:id==n?1:0;sem.implicitHydrogens=id==c?2:id==n||id==me?3:0;d.setAtomSemantics(id,sem);}d.extensions(ObjectRef(ObjectKind::Atom,n)).set("pst.attr.MoleculeStudioChargePosition","-0.9 -0.7");auto original=d.digest();std::vector<ObjectRef> made;auto e=mechanism::generateNextStep(d,{{ObjectRef(ObjectKind::Atom,o),ObjectRef(ObjectKind::Atom,me)},{ObjectRef(ObjectKind::Bond,ci),ObjectRef(ObjectKind::Atom,i)}},&made);require(e.ok(),"strict methylation with remote manually positioned charge: "+e.message);
        bool preserved=false;for(auto ref:made)if(ref.kind==ObjectKind::Atom&&studio_mechanism_products::sourceAtom(d,ref.id)==n){auto v=d.extensions(ref).findValue("pst.attr.MoleculeStudioChargePosition");preserved=v&&*v=="-0.9 -0.7";}require(preserved,"strict generated product preserves authored charge offset");
    }
    // Pointer capture must follow the newly displayed left-hand charge.
    {
        s.cancel();s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());ObjectId sulfur,parent,target;s.doc.addAtom(Vec2(80,80),16,&sulfur);s.doc.addAtom(Vec2(105,66),6,&parent);s.doc.addAtom(Vec2(155,105),6,&target);s.doc.addBond(sulfur,parent,nullptr);auto sem=s.doc.atoms().alive(sulfur)->semantics;sem.charge=-1;sem.implicitHydrogens=0;s.doc.setAtomSemantics(sulfur,sem);s.refresh();s.fit();s.activateCommand("chooseArrowTool_90_CW");auto area=arrows::mechanismVisualBoxes(s.doc).at(sulfur).charge;auto point=(area.min+area.max)*.5,to=s.doc.atoms().alive(target)->position;require(s.gesture(PointerPhase::Down,point).ok()&&s.gesture(PointerPhase::Move,to).ok()&&s.gesture(PointerPhase::Up,to).ok(),"draw from left charge");arrows::ArrowParams p;bool ok=false;arrows::readArrow(s.doc,0,&p,&ok);require(ok&&p.electronSource==ObjectRef(ObjectKind::Atom,sulfur)&&p.sourceVisualAnchor==2,"left charge capture retains the correct sulfur atom and charge site");
    }
    const auto fixture=dir+"/user-charge-input.r62doc";
    if(GetFileAttributesW(W(fixture).c_str())!=INVALID_FILE_ATTRIBUTES){
        s.cancel();s.history.clear();require(s.open(fixture).ok(),"open actual CS2 addition copy");auto before=s.doc.digest();auto count=s.doc.stats().aliveAtoms;s.selected={ObjectRef(ObjectKind::Arrow,3),ObjectRef(ObjectKind::Arrow,4)};app.generateMechanismStep();require(s.doc.stats().aliveAtoms==count+14,"actual CS2 addition makes fourteen product atoms");bool correct=false;for(auto ref:s.selected)if(ref.kind==ObjectKind::Atom){auto a=s.doc.atoms().alive(ref.id);if(a->element==16&&a->semantics.charge==-1){auto visual=arrows::mechanismVisualBoxes(s.doc).at(a->id);correct=visual.hasCharge&&visual.charge.max.x<arrows::mechanismLabelEnvelope(visual).min.x;}}require(correct,"actual generated sulfur minus is on the left");require(s.undo().ok()&&s.doc.digest()==before,"automatic left charge generation undoes atomically");
    }
    s.doc=display.doc;s.history.clear();s.selected.clear();s.refresh();s.fit();app.invalidate();require(s.save(dir+"/automatic-charge-sides.cdxml",true).ok(),"save automatic charge side examples");app.screenshot(dir+"/automatic-charge-sides.png");Session reopened;require(reopened.open(dir+"/automatic-charge-sides.cdxml").ok(),"reopen automatic charge display");
    std::ofstream(dir+"/automatic-charge-sides.json")<<"{\"display_cases\":"<<cases<<",\"negative_and_positive\":true,\"multiple_charge_magnitude\":true,\"manual_position_preserved\":true,\"left_charge_capture\":true}";
}
